# This crashes with: TypeError: unsupported operand type(s) result = calculate_average(None) ```

### Fix Request ```python prompt = """ Fix this function that crashes when passed None:

def calculate_average(numbers): total = sum(numbers) return total / len(numbers)

The function should handle None, empty lists, and non-numeric values gracefully. """

response = orchestrator.execute(prompt, agent="claude") ```

### Fixed Code ```python def calculate_average(numbers): """ Calculate the average of a list of numbers.

Args: numbers: List of numeric values or None

Returns: float: Average value, or None if input is invalid """ # Handle None input if numbers is None: return None

# Handle empty list if not numbers: return 0

# Filter out non-numeric values numeric_values = [] for num in numbers: try: numeric_values.append(float(num)) except (TypeError, ValueError): continue

# Return None if no valid numbers found if not numeric_values: return None

return sum(numeric_values) / len(numeric_values) ```

## Example 2: Memory Leak Fix

### Problem Code ```javascript class EventManager { constructor() { this.events = {}; }

on(event, callback) { if (!this.events[event]) { this.events[event] = []; } this.events[event].push(callback); }

emit(event, data) { if (this.events[event]) { this.events[event].forEach(cb => cb(data)); } } } ```

### Fix Request ```python prompt = """ Fix the memory leak in this JavaScript EventManager class. The class never removes event listeners, causing memory leaks. Add an 'off' method and ensure proper cleanup. """

response = orchestrator.execute(prompt, agent="claude") ```

### Fixed Code ```javascript class EventManager { constructor() { this.events = {}; this.eventIds = new WeakMap(); this.nextId = 0; }

on(event, callback) { if (!this.events[event]) { this.events[event] = []; }

// Store callback with unique ID for removal const id = this.nextId++; const callbackWrapper = { id, callback }; this.events[event].push(callbackWrapper); this.eventIds.set(callback, id);

// Return unsubscribe function return () => this.off(event, callback); }

off(event, callback) { if (!this.events[event]) return;

const id = this.eventIds.get(callback); if (id !== undefined) { this.events[event] = this.events[event].filter( wrapper => wrapper.id !== id ); this.eventIds.delete(callback);

// Clean up empty event arrays if (this.events[event].length === 0) { delete this.events[event]; } } }

emit(event, data) { if (this.events[event]) { this.events[event].forEach(wrapper => wrapper.callback(data) ); } }

// Clear all listeners for an event removeAllListeners(event) { if (event) { delete this.events[event]; } else { this.events = {}; } }

// Cleanup method for destroying the instance destroy() { this.events = {}; this.eventIds = new WeakMap(); } } ```

## Example 3: Race Condition Fix

### Problem Code ```python import threading

class Counter: def __init__(self): self.count = 0

def increment(self): temp = self.count # Simulating some processing temp = temp + 1 self.count = temp ```

### Fix Request ```python prompt = """ Fix the race condition in this Counter class that occurs when multiple threads call increment() simultaneously. """

response = orchestrator.execute(prompt, agent="claude") ```

### Fixed Code ```python import threading from contextlib import contextmanager

class Counter: def __init__(self): self.count = 0 self._lock = threading.Lock()

def increment(self): """Thread-safe increment operation.""" with self._lock: temp = self.count # Simulating some processing temp = temp + 1 self.count = temp

def decrement(self): """Thread-safe decrement operation.""" with self._lock: self.count -= 1

def get_value(self): """Thread-safe read operation.""" with self._lock: return self.count

@contextmanager def batch_operation(self): """Context manager for batch operations.""" self._lock.acquire() try: yield self finally: self._lock.release()

# Usage example: counter = Counter()

# Batch operations with counter.batch_operation(): for _ in range(100): counter.count += 1 # Direct access within context ```

